1	package gateway
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"log/slog"
11		"net/http"
12		"net/http/httputil"
13		"net/url"
14		"os"
15		"path/filepath"
16		"slices"
17		"strings"
18		"sync"
19		"sync/atomic"
20		"time"
21	
22		"github.com/nogo/wire/internal/config"
23		"github.com/nogo/wire/internal/monitor"
24		"github.com/nogo/wire/internal/process"
25	)
26	
27	// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
28	type nctxProvider interface {
29		NCtx(model string) int
30	}
31	
32	// processManager is the subset of process.Manager the Gateway depends on.
33	type processManager interface {
34		Loaded(name string) bool
35		// LoadOrGet returns the backend address for the named model, loading it on
36		// demand if not already running. The caller must call release() when the
37		// proxied request completes to decrement the in-flight counter.
38		LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error)
39		// ListModels returns all known models in non-idle states.
40		ListModels() []monitor.ModelInfo
41	}
42	
43	// hfCache caches HF model IDs with a TTL to avoid repeated filesystem I/O.
44	type hfCache struct {
45		mu    sync.Mutex
46		ids   []string
47		until time.Time
48	}
49	
50	func (c *hfCache) get(ttl time.Duration) ([]string, bool) {
51		c.mu.Lock()
52		defer c.mu.Unlock()
53		if time.Now().Before(c.until) {
54			return c.ids, true
55		}
56		return nil, false
57	}
58	
59	func (c *hfCache) set(ids []string, ttl time.Duration) {
60		c.mu.Lock()
61		defer c.mu.Unlock()
62		c.ids = ids
63		c.until = time.Now().Add(ttl)
64	}
65	
66	// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
67	type Gateway struct {
68		cfg        atomic.Pointer[config.Config]
69		mgr        processManager
70		log        *slog.Logger
71		affinity   *affinityTable
72		hub        nctxProvider
73		remote     *monitor.RemoteTracker
74		discovery  *monitor.ModelDiscovery
75		server     *http.Server
76		hfCacheDir string  // HuggingFace hub cache directory; empty disables scanning
77		hfCache    hfCache // cached HF model IDs
78	}
79	
80	// New creates a Gateway backed by the given process manager.
81	// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
82	// remote may be nil; when non-nil, remote provider requests are tracked.
83	func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
84		g := newGateway(cfg, mgr, hub, remote, discovery, log)
85		if home, err := os.UserHomeDir(); err == nil {
86			g.hfCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
87		}
88		return g
89	}
90	
91	func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
92		// Build affinity table from warmup models.
93		modelSlots := make(map[string]int, len(cfg.Warmup))
94		for _, name := range cfg.Warmup {
95			if params, ok := cfg.MatchModel(name); ok {
96				modelSlots[name] = params.Slots
97			}
98		}
99	
100		g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
101		g.cfg.Store(cfg)
102		// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
103		// a non-nil interface value, which would cause g.hub == nil checks to fail.
104		if hub != nil {
105			g.hub = hub
106		}
107	
108		mux := http.NewServeMux()
109		mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
110		mux.HandleFunc("POST /v1/completions", g.handleRoute)
111		mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
112		mux.HandleFunc("POST /v1/rerank", g.handleRoute)
113		mux.HandleFunc("GET /v1/models", g.handleModels)
114		mux.HandleFunc("GET /health", g.handleHealth)
115	
116		if hub != nil {
117			mux.HandleFunc("GET /monitor", monitor.HandlePage)
118			mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
119		}
120	
121		g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
122		return g
123	}
124	
125	// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
126	func (g *Gateway) ListenAndServe(ctx context.Context) error {
127		errCh := make(chan error, 1)
128		go func() {
129			if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
130				errCh <- err
131			}
132		}()
133		select {
134		case err := <-errCh:
135			return err
136		case <-ctx.Done():
137			shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
138			defer cancel()
139			return g.server.Shutdown(shutCtx)
140		}
141	}
142	
143	// UpdateConfig atomically replaces the gateway's config. New requests will use
144	// the updated model patterns and params immediately.
145	func (g *Gateway) UpdateConfig(cfg *config.Config) {
146		g.cfg.Store(cfg)
147	}
148	
149	// handleRoute extracts the model field from the JSON body and proxies to the matching process.
150	// If the model is known but not loaded, it is started on demand; the HTTP connection
151	// is held open until the model becomes healthy.
152	func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
153		// Read body once for all operations: model extraction, token estimation, slot affinity.
154		allBody, err := io.ReadAll(r.Body)
155		if err != nil {
156			writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
157			return
158		}
159	
160		var payload struct {
161			Model string `json:"model"`
162		}
163		if err := json.Unmarshal(allBody, &payload); err != nil {
164			writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
165			return
166		}
167		if payload.Model == "" {
168			writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
169			return
170		}
171	
172		currentCfg := g.cfg.Load()
173		params, ok := currentCfg.MatchModel(payload.Model)
174		var snap monitor.DiscoverySnapshot
175		if !ok && g.discovery != nil {
176			snap = g.discovery.Snapshot()
177			if dm, found := snap.Lookup(payload.Model); found {
178				if _, provOk := currentCfg.Providers[dm.Provider]; provOk {
179					params = config.ModelParams{Provider: dm.Provider}
180					ok = true
181				}
182			}
183		}
184		if !ok {
185			writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
186			return
187		}
188	
189		if params.IsRemote() {
190			g.handleRemote(w, r, payload.Model, params, currentCfg, allBody)
191			return // handleRemote handles body rewrite if needed
192		}
193	
194		addr, release, err := g.mgr.LoadOrGet(r.Context(), payload.Model, params)
195		if err != nil {
196			if errors.Is(err, context.DeadlineExceeded) {
197				writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out: "+err.Error(), "load_timeout")
198				return
199			}
200			writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
201			return
202		}
203		defer release()
204	
205		if g.hub != nil {
206			if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
207				if est := estimateTokens(allBody); est > 0 && est > nCtx*9/10 {
208					writeError(w, http.StatusBadRequest, "invalid_request_error",
209						fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
210						"context_length_exceeded")
211					return
212				}
213			}
214		}
215	
216		g.affinity.Register(payload.Model, params.Slots)
217	
218		hash := prefixHash(allBody)
219		if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
220			allBody = injectSlot(allBody, slotID)
221		}
222		r.Body = io.NopCloser(bytes.NewReader(allBody))
223		r.ContentLength = int64(len(allBody))
224	
225		target, parseErr := url.Parse(addr)
226		if parseErr != nil {
227			writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
228			return
229		}
230	
231		proxy := &httputil.ReverseProxy{
232			Rewrite: func(pr *httputil.ProxyRequest) {
233				pr.SetURL(target)
234				pr.Out.Host = target.Host
235			},
236			FlushInterval:  -1,
237			ModifyResponse: rewriteContextLengthError,
238			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
239				g.log.Error("proxy error", "model", payload.Model, "error", err)
240				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
241			},
242		}
243	
244		proxy.ServeHTTP(w, r)
245	}
246	
247	// handleModels returns all known models with their current status.
248	func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
249		type modelObj struct {
250			ID           string   `json:"id"`
251			Object       string   `json:"object"`
252			Type         string   `json:"type"`
253			Status       string   `json:"status,omitempty"`
254			Capabilities []string `json:"capabilities,omitempty"`
255			Provider     string   `json:"provider,omitempty"`
256		}
257		type modelsResp struct {
258			Object string     `json:"object"`
259			Data   []modelObj `json:"data"`
260		}
261	
262		models := g.Models()
263		data := make([]modelObj, 0, len(models))
264		for _, m := range models {
265			data = append(data, modelObj{
266				ID:           m.ID,
267				Object:       m.Object,
268				Type:         m.Type,
269				Status:       m.Status,
270				Capabilities: m.Capabilities,
271				Provider:     m.Provider,
272			})
273		}
274	
275		w.Header().Set("Content-Type", "application/json")
276		json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
277	}
278	
279	// Models returns all known models as ModelInfo slice.
280	func (g *Gateway) Models() []monitor.ModelInfo {
281		cfg := g.cfg.Load()
282		var models []monitor.ModelInfo
283	
284		// Local models from Manager (loaded/running)
285		localModels := g.mgr.ListModels()
286		for _, mi := range localModels {
287			obj := monitor.ModelInfo{
288				ID:     mi.ID,
289				Object: "model",
290				Type:   "local",
291				Status: mi.Status,
292			}
293			if p, ok := cfg.MatchModel(mi.ID); ok {
294				obj.Capabilities = p.Capabilities
295			}
296			models = append(models, obj)
297		}
298	
299		listed := make(map[string]bool, len(models))
300		for _, m := range models {
301			listed[m.ID] = true
302		}
303	
304		// HF cache models (local but not loaded)
305		for _, cm := range g.scanHFCache() {
306			if listed[cm] {
307				continue
308			}
309			models = append(models, monitor.ModelInfo{
310				ID:     cm,
311				Object: "model",
312				Type:   "local",
313				Status: "available",
314			})
315			listed[cm] = true
316		}
317	
318		// Configured remote models
319		configuredRemote := make(map[string]bool)
320		for pattern, p := range cfg.Models {
321			if !p.IsRemote() {
322				continue
323			}
324			configuredRemote[pattern] = true
325			models = append(models, monitor.ModelInfo{
326				ID:           pattern,
327				Object:       "model",
328				Type:         "remote",
329				Status:       "available",
330				Capabilities: p.Capabilities,
331				Provider:     p.Provider,
332			})
333		}
334	
335		// Discovered remote models
336		if g.discovery != nil {
337			for _, dm := range g.discovery.Snapshot().AllModels() {
338				if configuredRemote[dm.ID] {
339					continue
340				}
341				models = append(models, monitor.ModelInfo{
342					ID:       dm.ID,
343					Object:   "model",
344					Type:     "remote",
345					Status:   "available",
346					Provider: dm.Provider,
347				})
348			}
349		}
350	
351		return models
352	}
353	
354	// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
355	func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
356		w.Header().Set("Content-Type", "application/json")
357		if slices.ContainsFunc(g.cfg.Load().Warmup, g.mgr.Loaded) {
358			w.WriteHeader(http.StatusOK)
359			json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
360			return
361		}
362		w.WriteHeader(http.StatusServiceUnavailable)
363		json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
364	}
365	
366	// handleRemote proxies a request to a remote OpenAI-compatible provider,
367	// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
368	func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
369		provider, ok := cfg.Providers[params.Provider]
370		if !ok {
371			writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
372			return
373		}
374	
375		if params.UpstreamModel != "" {
376			var obj map[string]json.RawMessage
377			if err := json.Unmarshal(body, &obj); err == nil {
378				if raw, err := json.Marshal(params.UpstreamModel); err == nil {
379					obj["model"] = raw
380					if rewritten, err := json.Marshal(obj); err == nil {
381						body = rewritten
382					}
383				}
384			}
385		}
386		r.Body = io.NopCloser(bytes.NewReader(body))
387		r.ContentLength = int64(len(body))
388	
389		baseTarget, err := url.Parse(provider.BaseURL)
390		if err != nil {
391			writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
392			return
393		}
394	
395		apiKey := provider.APIKey
396		reqPath := r.URL.Path
397		upstreamModel := params.UpstreamModel
398		if upstreamModel == "" {
399			upstreamModel = modelName
400		}
401	
402		// Track remote request metrics.
403		var done func(int64, int)
404		if g.remote != nil {
405			done = g.remote.Start(modelName, params.Provider)
406		}
407		start := time.Now()
408	
409		proxy := &httputil.ReverseProxy{
410			Rewrite: func(pr *httputil.ProxyRequest) {
411				pr.SetURL(baseTarget)
412				pr.Out.URL.Path = baseTarget.Path + reqPath
413				pr.Out.Host = baseTarget.Host
414				pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
415			},
416			FlushInterval: -1,
417			ModifyResponse: func(resp *http.Response) error {
418				resp.Header.Set("X-Wire-Model", upstreamModel)
419				if done != nil {
420					done(time.Since(start).Nanoseconds(), resp.StatusCode)
421					done = nil // prevent double-call
422				}
423				return rewriteContextLengthError(resp)
424			},
425			ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
426				g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
427				if done != nil {
428					done(time.Since(start).Nanoseconds(), 502)
429					done = nil
430				}
431				writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
432			},
433		}
434	
435		proxy.ServeHTTP(w, r)
436	}
437	
438	// estimateTokens approximates the token count of a request body using a
439	// chars/4 heuristic. It extracts text from messages[].content (chat) and the
440	// input field (embeddings). Returns 0 on parse failure or empty content.
441	func estimateTokens(body []byte) int {
442		var req struct {
443			Messages []struct {
444				Content json.RawMessage `json:"content"`
445			} `json:"messages"`
446			Input json.RawMessage `json:"input"`
447		}
448		if err := json.Unmarshal(body, &req); err != nil {
449			return 0
450		}
451	
452		total := 0
453		for _, msg := range req.Messages {
454			if len(msg.Content) == 0 {
455				continue
456			}
457			var s string
458			if err := json.Unmarshal(msg.Content, &s); err == nil {
459				total += len(s)
460				continue
461			}
462			var parts []struct {
463				Text string `json:"text"`
464			}
465			if err := json.Unmarshal(msg.Content, &parts); err == nil {
466				for _, p := range parts {
467					total += len(p.Text)
468				}
469			}
470		}
471	
472		if len(req.Input) > 0 {
473			var s string
474			if err := json.Unmarshal(req.Input, &s); err == nil {
475				total += len(s)
476			} else {
477				var arr []string
478				if err := json.Unmarshal(req.Input, &arr); err == nil {
479					for _, s := range arr {
480						total += len(s)
481					}
482				}
483			}
484		}
485	
486		return total / 4
487	}
488	
489	// rewriteContextLengthError inspects non-2xx upstream responses for a
490	// context_length_exceeded error code and rewrites the status to 400 to match
491	// the OpenAI API standard. llama-server returns these as 500.
492	func rewriteContextLengthError(resp *http.Response) error {
493		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
494			return nil
495		}
496	
497		body, err := io.ReadAll(resp.Body)
498		resp.Body.Close()
499		if err != nil {
500			resp.Body = io.NopCloser(bytes.NewReader(nil))
501			return nil
502		}
503	
504		var envelope struct {
505			Error struct {
506				Code string `json:"code"`
507			} `json:"error"`
508		}
509		if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
510			resp.StatusCode = http.StatusBadRequest
511			resp.Status = http.StatusText(http.StatusBadRequest)
512		}
513	
514		resp.Body = io.NopCloser(bytes.NewReader(body))
515		return nil
516	}
517	
518	const hfCacheTTL = 30 * time.Second
519	
520	// scanHFCache returns cached model IDs (org/repo:QUANT) for all GGUF files
521	// found in the HuggingFace hub cache. Results are cached for 30s to avoid
522	// repeated filesystem I/O on /v1/models calls.
523	func (g *Gateway) scanHFCache() []string {
524		if g.hfCacheDir == "" {
525			return nil
526		}
527		if ids, ok := g.hfCache.get(hfCacheTTL); ok {
528			return ids
529		}
530	
531		entries, err := os.ReadDir(g.hfCacheDir)
532		if err != nil {
533			return nil
534		}
535	
536		var models []string
537		for _, entry := range entries {
538			name := entry.Name()
539			if !entry.IsDir() || !strings.HasPrefix(name, "models--") {
540				continue
541			}
542			// models--org--repo → org/repo
543			parts := strings.SplitN(name, "--", 3)
544			if len(parts) != 3 {
545				continue
546			}
547			repo := parts[1] + "/" + parts[2]
548	
549			// Walk snapshots for .gguf files.
550			snapshotsDir := filepath.Join(g.hfCacheDir, name, "snapshots")
551			snapshots, err := os.ReadDir(snapshotsDir)
552			if err != nil {
553				continue
554			}
555			seen := make(map[string]bool)
556			for _, snap := range snapshots {
557				if !snap.IsDir() {
558					continue
559				}
560				ggufs, err := filepath.Glob(filepath.Join(snapshotsDir, snap.Name(), "*.gguf"))
561				if err != nil {
562					continue
563				}
564				for _, path := range ggufs {
565					base := strings.TrimSuffix(filepath.Base(path), ".gguf")
566					// Skip auxiliary files (e.g. mmproj-BF16.gguf).
567					if strings.HasPrefix(base, "mmproj") {
568						continue
569					}
570					// Extract quant: look for Q prefix after the last dash-or-dot, but handle
571					// compound quants like Q5_K_M. The pattern is: model-name[-size]Q<num>[_<variant>]
572					// e.g. "Qwen3-4B-Q8_0" → "Q8_0", "Qwen3-4B-Q5_K_M" → "Q5_K_M"
573					quant := extractQuant(base)
574					if quant == "" {
575						continue
576					}
577					id := repo + ":" + quant
578					if !seen[id] {
579						seen[id] = true
580						models = append(models, id)
581					}
582				}
583			}
584		}
585		g.hfCache.set(models, hfCacheTTL)
586		return models
587	}
588	
589	// extractQuant extracts the quantization suffix from a GGUF filename.
590	// Handles patterns like "Qwen3-4B-Q8_0", "Qwen3-4B-Q5_K_M", "Phi-4-mini-instruct.Q8_0".
591	// Returns empty string if no valid quant is found.
592	func extractQuant(base string) string {
593		// Find last Q<num> and stop at -XB boundary (e.g., -4B, -8B)
594		for i := len(base) - 1; i >= 0; i-- {
595			if i > 0 && base[i] == 'B' && base[i-1] >= '0' && base[i-1] <= '9' {
596				break
597			}
598			if i+1 < len(base) && base[i] == 'Q' && base[i+1] >= '0' && base[i+1] <= '9' {
599				return base[i:]
600			}
601		}
602		return ""
603	}
604	
605	// writeError writes an OpenAI-format JSON error response.
606	func writeError(w http.ResponseWriter, status int, errType, message, code string) {
607		w.Header().Set("Content-Type", "application/json")
608		w.WriteHeader(status)
609		json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
610			"error": map[string]any{
611				"message": message,
612				"type":    errType,
613				"code":    code,
614			},
615		})
616	}
