package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/monitor"
	"github.com/nogo/wire/internal/process"
)

// nctxProvider wraps the NCtx lookup; *monitor.Hub satisfies this interface.
type nctxProvider interface {
	NCtx(model string) int
}

// processManager is the subset of process.Manager the Gateway depends on.
type processManager interface {
	Loaded(name string) bool
	// LoadOrGet returns the backend address for the named model, loading it on
	// demand if not already running. The caller must call release() when the
	// proxied request completes to decrement the in-flight counter.
	LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error)
	// ListModels returns all known models in non-idle states.
	ListModels() []monitor.ModelInfo
}

// hfCache caches HF model IDs with a TTL to avoid repeated filesystem I/O.
type hfCache struct {
	mu    sync.Mutex
	ids   []string
	until time.Time
}

func (c *hfCache) get(ttl time.Duration) ([]string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if time.Now().Before(c.until) {
		return c.ids, true
	}
	return nil, false
}

func (c *hfCache) set(ids []string, ttl time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.ids = ids
	c.until = time.Now().Add(ttl)
}

// Gateway is an HTTP reverse-proxy that routes OpenAI-compatible requests to llama-server processes.
type Gateway struct {
	cfg        atomic.Pointer[config.Config]
	mgr        processManager
	log        *slog.Logger
	affinity   *affinityTable
	hub        nctxProvider
	remote     *monitor.RemoteTracker
	discovery  *monitor.ModelDiscovery
	server     *http.Server
	hfCacheDir string  // HuggingFace hub cache directory; empty disables scanning
	hfCache    hfCache // cached HF model IDs
}

// New creates a Gateway backed by the given process manager.
// hub may be nil; when non-nil, /monitor and /monitor/ws routes are registered.
// remote may be nil; when non-nil, remote provider requests are tracked.
func New(cfg *config.Config, mgr *process.Manager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
	g := newGateway(cfg, mgr, hub, remote, discovery, log)
	if home, err := os.UserHomeDir(); err == nil {
		g.hfCacheDir = filepath.Join(home, ".cache", "huggingface", "hub")
	}
	return g
}

func newGateway(cfg *config.Config, mgr processManager, hub *monitor.Hub, remote *monitor.RemoteTracker, discovery *monitor.ModelDiscovery, log *slog.Logger) *Gateway {
	// Build affinity table from warmup models.
	modelSlots := make(map[string]int, len(cfg.Warmup))
	for _, name := range cfg.Warmup {
		if params, ok := cfg.MatchModel(name); ok {
			modelSlots[name] = params.Slots
		}
	}

	g := &Gateway{mgr: mgr, log: log, affinity: newAffinityTable(modelSlots), remote: remote, discovery: discovery}
	g.cfg.Store(cfg)
	// Store hub as nctxProvider nil-safely: a nil *monitor.Hub must not become
	// a non-nil interface value, which would cause g.hub == nil checks to fail.
	if hub != nil {
		g.hub = hub
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /v1/chat/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/completions", g.handleRoute)
	mux.HandleFunc("POST /v1/embeddings", g.handleRoute)
	mux.HandleFunc("POST /v1/rerank", g.handleRoute)
	mux.HandleFunc("GET /v1/models", g.handleModels)
	mux.HandleFunc("GET /health", g.handleHealth)

	if hub != nil {
		mux.HandleFunc("GET /monitor", monitor.HandlePage)
		mux.HandleFunc("GET /monitor/ws", monitor.HandleWS(hub))
	}

	g.server = &http.Server{Addr: cfg.Listen, Handler: mux}
	return g
}

// ListenAndServe starts the HTTP server and shuts it down when ctx is cancelled.
func (g *Gateway) ListenAndServe(ctx context.Context) error {
	errCh := make(chan error, 1)
	go func() {
		if err := g.server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			errCh <- err
		}
	}()
	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
		shutCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		return g.server.Shutdown(shutCtx)
	}
}

// UpdateConfig atomically replaces the gateway's config. New requests will use
// the updated model patterns and params immediately.
func (g *Gateway) UpdateConfig(cfg *config.Config) {
	g.cfg.Store(cfg)
}

// handleRoute extracts the model field from the JSON body and proxies to the matching process.
// If the model is known but not loaded, it is started on demand; the HTTP connection
// is held open until the model becomes healthy.
func (g *Gateway) handleRoute(w http.ResponseWriter, r *http.Request) {
	// Read body once for all operations: model extraction, token estimation, slot affinity.
	allBody, err := io.ReadAll(r.Body)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "failed to read body", "bad_request")
		return
	}

	var payload struct {
		Model string `json:"model"`
	}
	if err := json.Unmarshal(allBody, &payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "invalid JSON: "+err.Error(), "bad_request")
		return
	}
	if payload.Model == "" {
		writeError(w, http.StatusBadRequest, "invalid_request_error", "missing model field", "bad_request")
		return
	}

	currentCfg := g.cfg.Load()
	params, ok := currentCfg.MatchModel(payload.Model)
	var snap monitor.DiscoverySnapshot
	if !ok && g.discovery != nil {
		snap = g.discovery.Snapshot()
		if dm, found := snap.Lookup(payload.Model); found {
			if _, provOk := currentCfg.Providers[dm.Provider]; provOk {
				params = config.ModelParams{Provider: dm.Provider}
				ok = true
			}
		}
	}
	if !ok {
		writeError(w, http.StatusNotFound, "invalid_request_error", "unknown model: "+payload.Model, "model_not_found")
		return
	}

	if params.IsRemote() {
		g.handleRemote(w, r, payload.Model, params, currentCfg, allBody)
		return // handleRemote handles body rewrite if needed
	}

	addr, release, err := g.mgr.LoadOrGet(r.Context(), payload.Model, params)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			writeError(w, http.StatusGatewayTimeout, "server_error", "model load timed out: "+err.Error(), "load_timeout")
			return
		}
		writeError(w, http.StatusServiceUnavailable, "server_error", err.Error(), "model_not_loaded")
		return
	}
	defer release()

	if g.hub != nil {
		if nCtx := g.hub.NCtx(payload.Model); nCtx > 0 {
			if est := estimateTokens(allBody); est > 0 && est > nCtx*9/10 {
				writeError(w, http.StatusBadRequest, "invalid_request_error",
					fmt.Sprintf("estimated %d tokens exceeds context window of %d (n_ctx)", est, nCtx),
					"context_length_exceeded")
				return
			}
		}
	}

	g.affinity.Register(payload.Model, params.Slots)

	hash := prefixHash(allBody)
	if slotID, assigned := g.affinity.Assign(payload.Model, hash); assigned {
		allBody = injectSlot(allBody, slotID)
	}
	r.Body = io.NopCloser(bytes.NewReader(allBody))
	r.ContentLength = int64(len(allBody))

	target, parseErr := url.Parse(addr)
	if parseErr != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "invalid backend URL", "internal_error")
		return
	}

	proxy := &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(target)
			pr.Out.Host = target.Host
		},
		FlushInterval:  -1,
		ModifyResponse: rewriteContextLengthError,
		ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
			g.log.Error("proxy error", "model", payload.Model, "error", err)
			writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
		},
	}

	proxy.ServeHTTP(w, r)
}

// handleModels returns all known models with their current status.
func (g *Gateway) handleModels(w http.ResponseWriter, _ *http.Request) {
	type modelObj struct {
		ID           string   `json:"id"`
		Object       string   `json:"object"`
		Type         string   `json:"type"`
		Status       string   `json:"status,omitempty"`
		Capabilities []string `json:"capabilities,omitempty"`
		Provider     string   `json:"provider,omitempty"`
	}
	type modelsResp struct {
		Object string     `json:"object"`
		Data   []modelObj `json:"data"`
	}

	models := g.Models()
	data := make([]modelObj, 0, len(models))
	for _, m := range models {
		data = append(data, modelObj{
			ID:           m.ID,
			Object:       m.Object,
			Type:         m.Type,
			Status:       m.Status,
			Capabilities: m.Capabilities,
			Provider:     m.Provider,
		})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(modelsResp{Object: "list", Data: data}) //nolint:errcheck
}

// Models returns all known models as ModelInfo slice.
func (g *Gateway) Models() []monitor.ModelInfo {
	cfg := g.cfg.Load()
	var models []monitor.ModelInfo

	// Local models from Manager (loaded/running)
	localModels := g.mgr.ListModels()
	for _, mi := range localModels {
		obj := monitor.ModelInfo{
			ID:     mi.ID,
			Object: "model",
			Type:   "local",
			Status: mi.Status,
		}
		if p, ok := cfg.MatchModel(mi.ID); ok {
			obj.Capabilities = p.Capabilities
		}
		models = append(models, obj)
	}

	listed := make(map[string]bool, len(models))
	for _, m := range models {
		listed[m.ID] = true
	}

	// HF cache models (local but not loaded)
	for _, cm := range g.scanHFCache() {
		if listed[cm] {
			continue
		}
		models = append(models, monitor.ModelInfo{
			ID:     cm,
			Object: "model",
			Type:   "local",
			Status: "available",
		})
		listed[cm] = true
	}

	// Configured remote models
	configuredRemote := make(map[string]bool)
	for pattern, p := range cfg.Models {
		if !p.IsRemote() {
			continue
		}
		configuredRemote[pattern] = true
		models = append(models, monitor.ModelInfo{
			ID:           pattern,
			Object:       "model",
			Type:         "remote",
			Status:       "available",
			Capabilities: p.Capabilities,
			Provider:     p.Provider,
		})
	}

	// Discovered remote models
	if g.discovery != nil {
		for _, dm := range g.discovery.Snapshot().AllModels() {
			if configuredRemote[dm.ID] {
				continue
			}
			models = append(models, monitor.ModelInfo{
				ID:       dm.ID,
				Object:   "model",
				Type:     "remote",
				Status:   "available",
				Provider: dm.Provider,
			})
		}
	}

	return models
}

// handleHealth returns 200 if at least one warmup model is healthy, 503 otherwise.
func (g *Gateway) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	if slices.ContainsFunc(g.cfg.Load().Warmup, g.mgr.Loaded) {
		w.WriteHeader(http.StatusOK)
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"}) //nolint:errcheck
		return
	}
	w.WriteHeader(http.StatusServiceUnavailable)
	json.NewEncoder(w).Encode(map[string]string{"status": "degraded"}) //nolint:errcheck
}

// handleRemote proxies a request to a remote OpenAI-compatible provider,
// bypassing the process manager entirely. body may be rewound if upstream_model rewrite is needed.
func (g *Gateway) handleRemote(w http.ResponseWriter, r *http.Request, modelName string, params config.ModelParams, cfg *config.Config, body []byte) {
	provider, ok := cfg.Providers[params.Provider]
	if !ok {
		writeError(w, http.StatusInternalServerError, "server_error", "unknown provider: "+params.Provider, "config_error")
		return
	}

	if params.UpstreamModel != "" {
		var obj map[string]json.RawMessage
		if err := json.Unmarshal(body, &obj); err == nil {
			if raw, err := json.Marshal(params.UpstreamModel); err == nil {
				obj["model"] = raw
				if rewritten, err := json.Marshal(obj); err == nil {
					body = rewritten
				}
			}
		}
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	r.ContentLength = int64(len(body))

	baseTarget, err := url.Parse(provider.BaseURL)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "server_error", "invalid provider URL", "config_error")
		return
	}

	apiKey := provider.APIKey
	reqPath := r.URL.Path
	upstreamModel := params.UpstreamModel
	if upstreamModel == "" {
		upstreamModel = modelName
	}

	// Track remote request metrics.
	var done func(int64, int)
	if g.remote != nil {
		done = g.remote.Start(modelName, params.Provider)
	}
	start := time.Now()

	proxy := &httputil.ReverseProxy{
		Rewrite: func(pr *httputil.ProxyRequest) {
			pr.SetURL(baseTarget)
			pr.Out.URL.Path = baseTarget.Path + reqPath
			pr.Out.Host = baseTarget.Host
			pr.Out.Header.Set("Authorization", "Bearer "+apiKey)
		},
		FlushInterval: -1,
		ModifyResponse: func(resp *http.Response) error {
			resp.Header.Set("X-Wire-Model", upstreamModel)
			if done != nil {
				done(time.Since(start).Nanoseconds(), resp.StatusCode)
				done = nil // prevent double-call
			}
			return rewriteContextLengthError(resp)
		},
		ErrorHandler: func(w http.ResponseWriter, _ *http.Request, err error) {
			g.log.Error("remote proxy error", "model", modelName, "provider", params.Provider, "error", err)
			if done != nil {
				done(time.Since(start).Nanoseconds(), 502)
				done = nil
			}
			writeError(w, http.StatusBadGateway, "server_error", "upstream error: "+err.Error(), "upstream_error")
		},
	}

	proxy.ServeHTTP(w, r)
}

// estimateTokens approximates the token count of a request body using a
// chars/4 heuristic. It extracts text from messages[].content (chat) and the
// input field (embeddings). Returns 0 on parse failure or empty content.
func estimateTokens(body []byte) int {
	var req struct {
		Messages []struct {
			Content json.RawMessage `json:"content"`
		} `json:"messages"`
		Input json.RawMessage `json:"input"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		return 0
	}

	total := 0
	for _, msg := range req.Messages {
		if len(msg.Content) == 0 {
			continue
		}
		var s string
		if err := json.Unmarshal(msg.Content, &s); err == nil {
			total += len(s)
			continue
		}
		var parts []struct {
			Text string `json:"text"`
		}
		if err := json.Unmarshal(msg.Content, &parts); err == nil {
			for _, p := range parts {
				total += len(p.Text)
			}
		}
	}

	if len(req.Input) > 0 {
		var s string
		if err := json.Unmarshal(req.Input, &s); err == nil {
			total += len(s)
		} else {
			var arr []string
			if err := json.Unmarshal(req.Input, &arr); err == nil {
				for _, s := range arr {
					total += len(s)
				}
			}
		}
	}

	return total / 4
}

// rewriteContextLengthError inspects non-2xx upstream responses for a
// context_length_exceeded error code and rewrites the status to 400 to match
// the OpenAI API standard. llama-server returns these as 500.
func rewriteContextLengthError(resp *http.Response) error {
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return nil
	}

	body, err := io.ReadAll(resp.Body)
	resp.Body.Close()
	if err != nil {
		resp.Body = io.NopCloser(bytes.NewReader(nil))
		return nil
	}

	var envelope struct {
		Error struct {
			Code string `json:"code"`
		} `json:"error"`
	}
	if json.Unmarshal(body, &envelope) == nil && envelope.Error.Code == "context_length_exceeded" {
		resp.StatusCode = http.StatusBadRequest
		resp.Status = http.StatusText(http.StatusBadRequest)
	}

	resp.Body = io.NopCloser(bytes.NewReader(body))
	return nil
}

const hfCacheTTL = 30 * time.Second

// scanHFCache returns cached model IDs (org/repo:QUANT) for all GGUF files
// found in the HuggingFace hub cache. Results are cached for 30s to avoid
// repeated filesystem I/O on /v1/models calls.
func (g *Gateway) scanHFCache() []string {
	if g.hfCacheDir == "" {
		return nil
	}
	if ids, ok := g.hfCache.get(hfCacheTTL); ok {
		return ids
	}

	entries, err := os.ReadDir(g.hfCacheDir)
	if err != nil {
		return nil
	}

	var models []string
	for _, entry := range entries {
		name := entry.Name()
		if !entry.IsDir() || !strings.HasPrefix(name, "models--") {
			continue
		}
		// models--org--repo → org/repo
		parts := strings.SplitN(name, "--", 3)
		if len(parts) != 3 {
			continue
		}
		repo := parts[1] + "/" + parts[2]

		// Walk snapshots for .gguf files.
		snapshotsDir := filepath.Join(g.hfCacheDir, name, "snapshots")
		snapshots, err := os.ReadDir(snapshotsDir)
		if err != nil {
			continue
		}
		seen := make(map[string]bool)
		for _, snap := range snapshots {
			if !snap.IsDir() {
				continue
			}
			ggufs, err := filepath.Glob(filepath.Join(snapshotsDir, snap.Name(), "*.gguf"))
			if err != nil {
				continue
			}
			for _, path := range ggufs {
				base := strings.TrimSuffix(filepath.Base(path), ".gguf")
				// Skip auxiliary files (e.g. mmproj-BF16.gguf).
				if strings.HasPrefix(base, "mmproj") {
					continue
				}
				// Extract quant: look for Q prefix after the last dash-or-dot, but handle
				// compound quants like Q5_K_M. The pattern is: model-name[-size]Q<num>[_<variant>]
				// e.g. "Qwen3-4B-Q8_0" → "Q8_0", "Qwen3-4B-Q5_K_M" → "Q5_K_M"
				quant := extractQuant(base)
				if quant == "" {
					continue
				}
				id := repo + ":" + quant
				if !seen[id] {
					seen[id] = true
					models = append(models, id)
				}
			}
		}
	}
	g.hfCache.set(models, hfCacheTTL)
	return models
}

// extractQuant extracts the quantization suffix from a GGUF filename.
// Handles patterns like "Qwen3-4B-Q8_0", "Qwen3-4B-Q5_K_M", "Phi-4-mini-instruct.Q8_0".
// Returns empty string if no valid quant is found.
func extractQuant(base string) string {
	// Find last Q<num> and stop at -XB boundary (e.g., -4B, -8B)
	for i := len(base) - 1; i >= 0; i-- {
		if i > 0 && base[i] == 'B' && base[i-1] >= '0' && base[i-1] <= '9' {
			break
		}
		if i+1 < len(base) && base[i] == 'Q' && base[i+1] >= '0' && base[i+1] <= '9' {
			return base[i:]
		}
	}
	return ""
}

// writeError writes an OpenAI-format JSON error response.
func writeError(w http.ResponseWriter, status int, errType, message, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(map[string]any{ //nolint:errcheck
		"error": map[string]any{
			"message": message,
			"type":    errType,
			"code":    code,
		},
	})
}

package process

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os/exec"
	"sort"
	"strconv"
	"sync"
	"sync/atomic"
	"syscall"
	"time"

	"github.com/nogo/wire/internal/config"
	"github.com/nogo/wire/internal/monitor"
)

// modelState represents the lifecycle state of a managed model process.
type modelState int

const (
	stateIdle      modelState = iota // not loaded or failed
	stateLoading                     // llama-server starting up
	stateLoaded                      // loaded and serving requests
	stateUnloading                   // unloading: SIGTERM sent, waiting for exit
)

func (s modelState) String() string {
	switch s {
	case stateIdle:
		return "idle"
	case stateLoading:
		return "loading"
	case stateLoaded:
		return "loaded"
	case stateUnloading:
		return "unloading"
	default:
		return "unknown"
	}
}

type procState struct {
	mu        sync.Mutex
	modelName string
	params    config.ModelParams
	port      int
	proc      *exec.Cmd
	startedAt time.Time
	restarts  int
	isWarmup  bool

	// State machine. state and ready are always updated together under mu.
	state   modelState
	ready   chan struct{} // closed when loading completes (success or failure); nil when idle
	loadErr error         // non-nil if the most recent load attempt failed

	// In-flight tracking and LRU.
	inflight atomic.Int64
	lastUsed time.Time

	// Per-model lifecycle control.
	cancel context.CancelFunc
	wg     sync.WaitGroup // Done when the supervisor goroutine exits
}

// addInflight increments the in-flight counter and updates lastUsed.
// Returns the address, release function, and no error.
func (ps *procState) addInflight(port int) (addr string, release func(), err error) {
	ps.inflight.Add(1)
	ps.mu.Lock()
	ps.lastUsed = time.Now()
	ps.mu.Unlock()
	return fmt.Sprintf("http://localhost:%d", port), func() { ps.inflight.Add(-1) }, nil
}

// Manager supervises llama-server child processes.
type Manager struct {
	cfg        *config.Config
	log        *slog.Logger
	cmdBuilder func(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd

	// healthTimeout overrides the 120s waitHealthy timeout. Zero means 120s.
	// Set in tests to speed up failure scenarios.
	healthTimeout time.Duration

	mu      sync.RWMutex
	procs   map[string]*procState
	ctx     context.Context    // manager root context (detached from any HTTP request)
	wg      sync.WaitGroup     // Done when all supervisors exit
	cancel  context.CancelFunc // cancels m.ctx
	eventCh chan monitor.ServerEvent
}

// New creates a Manager. It does not start any processes; call Start.
func New(cfg *config.Config, log *slog.Logger) *Manager {
	m := new(Manager)
	m.cfg = cfg
	m.log = log
	m.procs = make(map[string]*procState)
	m.eventCh = make(chan monitor.ServerEvent, 256)
	m.cmdBuilder = func(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd {
		return exec.CommandContext(ctx, "llama-server", buildArgs(modelName, params)...)
	}
	return m
}

// SetCmdBuilder replaces the default llama-server launcher. Used in tests to
// inject a fake process builder without starting real llama-server instances.
func (m *Manager) SetCmdBuilder(fn func(ctx context.Context, modelName string, params config.ModelParams) *exec.Cmd) {
	m.cmdBuilder = fn
}

// Events returns a receive-only channel of structured events from all managed processes.
func (m *Manager) Events() <-chan monitor.ServerEvent {
	return m.eventCh
}

// Snapshot returns a point-in-time snapshot of all managed processes.
func (m *Manager) Snapshot() []monitor.BackendStatus {
	m.mu.RLock()
	defer m.mu.RUnlock()

	result := make([]monitor.BackendStatus, 0, len(m.procs))
	for _, ps := range m.procs {
		ps.mu.Lock()
		pid := 0
		if ps.proc != nil && ps.proc.Process != nil {
			pid = ps.proc.Process.Pid
		}
		status := monitor.BackendStatus{
			Name:      ps.modelName,
			Model:     ps.modelName,
			Port:      ps.port,
			PID:       pid,
			Loaded:    ps.state == stateLoaded,
			Status:    ps.state.String(),
			StartedAt: ps.startedAt,
			Restarts:  ps.restarts,
		}
		ps.mu.Unlock()
		result = append(result, status)
	}
	return result
}

// RunningModels returns model names of all currently healthy processes.
func (m *Manager) RunningModels() []string {
	m.mu.RLock()
	defer m.mu.RUnlock()
	var names []string
	for name, ps := range m.procs {
		ps.mu.Lock()
		healthy := ps.state == stateLoaded
		ps.mu.Unlock()
		if healthy {
			names = append(names, name)
		}
	}
	return names
}

// ListModels returns all known models in any state except idle.
func (m *Manager) ListModels() []monitor.ModelInfo {
	m.mu.RLock()
	defer m.mu.RUnlock()
	result := make([]monitor.ModelInfo, 0, len(m.procs))
	for _, ps := range m.procs {
		ps.mu.Lock()
		state := ps.state
		name := ps.modelName
		ps.mu.Unlock()
		if state != stateIdle {
			result = append(result, monitor.ModelInfo{ID: name, Status: state.String()})
		}
	}
	return result
}

// Start launches supervisor goroutines for all warmup models.
// It returns immediately; health checks happen asynchronously.
func (m *Manager) Start(ctx context.Context) error {
	ctx, cancel := context.WithCancel(ctx)
	m.ctx = ctx
	m.cancel = cancel

	for _, modelName := range m.cfg.Warmup {
		params, ok := m.cfg.MatchModel(modelName)
		if !ok {
			cancel()
			return fmt.Errorf("warmup model %q does not match any pattern", modelName)
		}
		if err := m.startSupervisor(modelName, params, true); err != nil {
			cancel()
			return err
		}
	}
	return nil
}

// startSupervisor creates a procState and launches the supervisor goroutine.
// Must NOT hold m.mu.
func (m *Manager) startSupervisor(modelName string, params config.ModelParams, isWarmup bool) error {
	modelCtx, modelCancel := context.WithCancel(m.ctx)
	ps := &procState{
		modelName: modelName,
		params:    params,
		state:     stateLoading,
		ready:     make(chan struct{}),
		cancel:    modelCancel,
		isWarmup:  isWarmup,
	}

	m.mu.Lock()
	m.procs[modelName] = ps
	m.mu.Unlock()

	m.wg.Add(1)
	ps.wg.Add(1)
	go m.supervise(modelCtx, modelName)
	return nil
}

// Reload applies newCfg to the running manager. Models whose params changed are
// drained and restarted; models no longer matching any pattern are drained and
// removed; new warmup entries are started. Models with unchanged params keep
// serving without interruption.
//
// Global fields that require a process restart (e.g. listen address) are logged
// as warnings but not applied.
func (m *Manager) Reload(newCfg *config.Config) {
	if m.cfg.Listen != newCfg.Listen {
		m.log.Warn("listen address changed; requires restart to take effect",
			"old", m.cfg.Listen, "new", newCfg.Listen)
	}

	type drainOp struct {
		name      string
		ps        *procState
		newParams config.ModelParams
		restart   bool
		isWarmup  bool
	}

	newWarmupSet := make(map[string]bool, len(newCfg.Warmup))
	for _, name := range newCfg.Warmup {
		newWarmupSet[name] = true
	}

	m.mu.Lock()
	m.cfg = newCfg

	var ops []drainOp
	for name, ps := range m.procs {
		ps.mu.Lock()
		state := ps.state
		oldParams := ps.params
		wasWarmup := ps.isWarmup
		ps.mu.Unlock()

		if state != stateLoaded && state != stateLoading {
			continue
		}

		newParams, ok := newCfg.MatchModel(name)
		if !ok {
			m.log.Info("draining removed model", "model", name)
			ps.mu.Lock()
			ps.state = stateUnloading
			ps.mu.Unlock()
			ops = append(ops, drainOp{name: name, ps: ps})
			continue
		}

		if !oldParams.Equal(newParams) {
			m.log.Info("reloading model", "model", name)
			ps.mu.Lock()
			ps.state = stateUnloading
			ps.mu.Unlock()
			ops = append(ops, drainOp{
				name:      name,
				ps:        ps,
				newParams: newParams,
				restart:   true,
				isWarmup:  wasWarmup || newWarmupSet[name],
			})
			continue
		}

		if wasWarmup && !newWarmupSet[name] {
			m.log.Info("draining removed warmup model", "model", name)
			ps.mu.Lock()
			ps.state = stateUnloading
			ps.mu.Unlock()
			ops = append(ops, drainOp{name: name, ps: ps})
		}
	}
	m.mu.Unlock()

	// Cancel all affected models simultaneously, then wait for each to exit.
	// This runs outside m.mu to avoid deadlocking with the supervisor goroutine.
	for i := range ops {
		ops[i].ps.cancel()
	}
	for i := range ops {
		ops[i].ps.wg.Wait()
	}

	m.mu.Lock()
	for i := range ops {
		delete(m.procs, ops[i].name)
	}
	m.mu.Unlock()

	// Restart models whose params changed.
	for _, op := range ops {
		if op.restart {
			if err := m.startSupervisor(op.name, op.newParams, op.isWarmup); err != nil {
				m.log.Error("failed to restart model after reload", "model", op.name, "error", err)
			}
		}
	}

	// Start new warmup models not currently in procs.
	for _, name := range newCfg.Warmup {
		m.mu.RLock()
		_, exists := m.procs[name]
		m.mu.RUnlock()
		if exists {
			continue
		}
		params, ok := newCfg.MatchModel(name)
		if !ok {
			continue
		}
		m.log.Info("starting new warmup model", "model", name)
		if err := m.startSupervisor(name, params, true); err != nil {
			m.log.Error("failed to start new warmup model", "model", name, "error", err)
		}
	}
}

// Stop cancels all managed processes and waits for them to exit.
func (m *Manager) Stop() error {
	if m.cancel != nil {
		m.cancel()
	}
	m.wg.Wait()
	return nil
}

// Loaded reports whether a model's process is ready to serve requests.
func (m *Manager) Loaded(name string) bool {
	m.mu.RLock()
	ps, ok := m.procs[name]
	m.mu.RUnlock()
	if !ok {
		return false
	}
	ps.mu.Lock()
	defer ps.mu.Unlock()
	return ps.state == stateLoaded
}

// Addr returns the base URL for a healthy model's process.
func (m *Manager) Addr(name string) (string, bool) {
	m.mu.RLock()
	ps, ok := m.procs[name]
	m.mu.RUnlock()
	if !ok {
		return "", false
	}
	ps.mu.Lock()
	defer ps.mu.Unlock()
	if ps.port == 0 || ps.state != stateLoaded {
		return "", false
	}
	return fmt.Sprintf("http://localhost:%d", ps.port), true
}

// LoadOrGet returns the address of the named model, loading it on demand if
// necessary. Concurrent calls for the same unloaded model coalesce — one
// process starts and all waiters get the address when it becomes healthy.
//
// The caller must call the returned release function (typically via defer) when
// the proxied request completes. This decrements the in-flight counter and
// allows the model to be evicted once idle.
//
// Errors:
//   - context.Canceled / context.DeadlineExceeded: caller's context expired
//   - "model is shutting down": model is being drained
//   - "at capacity …": max_models reached with all models in use
//   - "model … load failed: …": llama-server failed to start or become healthy
func (m *Manager) LoadOrGet(ctx context.Context, modelName string, params config.ModelParams) (addr string, release func(), err error) {
	m.mu.Lock()

	if ps, ok := m.procs[modelName]; ok {
		ps.mu.Lock()
		state := ps.state
		ready := ps.ready
		port := ps.port
		ps.mu.Unlock()

		switch state {
		case stateLoaded:
			m.mu.Unlock()
			return ps.addInflight(port)

		case stateLoading:
			m.mu.Unlock()
			select {
			case <-ready:
			case <-ctx.Done():
				return "", func() {}, ctx.Err()
			}
			return m.checkLoaded(modelName)

		case stateUnloading:
			m.mu.Unlock()
			return "", func() {}, fmt.Errorf("model %q is shutting down", modelName)

		case stateIdle:
			delete(m.procs, modelName)
		}
	}

	if err := m.evictIfNeeded(); err != nil {
		m.mu.Unlock()
		return "", func() {}, err
	}

	if ps2, ok := m.procs[modelName]; ok {
		ps2.mu.Lock()
		state2 := ps2.state
		ready2 := ps2.ready
		port2 := ps2.port
		ps2.mu.Unlock()
		switch state2 {
		case stateLoaded:
			m.mu.Unlock()
			return ps2.addInflight(port2)
		case stateLoading:
			m.mu.Unlock()
			select {
			case <-ready2:
			case <-ctx.Done():
				return "", func() {}, ctx.Err()
			}
			return m.checkLoaded(modelName)
		}
	}

	// Create a new procState and start the supervisor.
	modelCtx, modelCancel := context.WithCancel(m.ctx)
	ps := &procState{
		modelName: modelName,
		params:    params,
		state:     stateLoading,
		ready:     make(chan struct{}),
		cancel:    modelCancel,
		isWarmup:  false,
	}
	m.procs[modelName] = ps
	ready := ps.ready
	m.mu.Unlock()

	m.publishEvent(monitor.ServerEvent{
		Time:    time.Now(),
		Backend: modelName,
		Kind:    monitor.EventModelLoad,
		Message: "loading on demand",
	})

	m.wg.Add(1)
	ps.wg.Add(1)
	go m.supervise(modelCtx, modelName)

	select {
	case <-ready:
	case <-ctx.Done():
		return "", func() {}, ctx.Err()
	}

	return m.checkLoaded(modelName)
}

// checkLoaded reads the outcome of a completed load (after ready has closed).
func (m *Manager) checkLoaded(modelName string) (addr string, release func(), err error) {
	m.mu.RLock()
	ps, ok := m.procs[modelName]
	m.mu.RUnlock()

	if !ok {
		return "", func() {}, fmt.Errorf("model %q load failed", modelName)
	}

	ps.mu.Lock()
	state := ps.state
	loadErr := ps.loadErr
	port := ps.port
	ps.mu.Unlock()

	if state != stateLoaded {
		if loadErr != nil {
			return "", func() {}, fmt.Errorf("model %q load failed: %w", modelName, loadErr)
		}
		return "", func() {}, fmt.Errorf("model %q load failed", modelName)
	}

	return ps.addInflight(port)
}

// evictIfNeeded evicts the LRU idle healthy model if we are at capacity.
//
// IMPORTANT: must be called with m.mu write-locked. It temporarily releases
// and re-acquires m.mu while waiting for the evicted supervisor to exit,
// so the caller must re-validate procs state after it returns.
func (m *Manager) evictIfNeeded() error {
	type candidate struct {
		name     string
		ps       *procState
		lastUsed time.Time
	}
	var candidates []candidate
	running := 0

	for name, ps := range m.procs {
		ps.mu.Lock()
		state := ps.state
		lu := ps.lastUsed
		ps.mu.Unlock()

		if state != stateIdle {
			running++
		}
		if state == stateLoaded && ps.inflight.Load() == 0 {
			candidates = append(candidates, candidate{name: name, ps: ps, lastUsed: lu})
		}
	}

	if running < m.cfg.MaxModels {
		return nil
	}
	if len(candidates) == 0 {
		return fmt.Errorf("at capacity (%d/%d models); all models have in-flight requests", running, m.cfg.MaxModels)
	}

	sort.Slice(candidates, func(i, j int) bool {
		return candidates[i].lastUsed.Before(candidates[j].lastUsed)
	})

	victim := candidates[0]
	victim.ps.mu.Lock()
	victim.ps.state = stateUnloading
	victim.ps.mu.Unlock()

	// Release the manager lock while waiting for the supervisor to exit.
	m.mu.Unlock()

	m.log.Info("evicting model (LRU)", "model", victim.name)
	m.publishEvent(monitor.ServerEvent{
		Time:    time.Now(),
		Backend: victim.name,
		Kind:    monitor.EventModelLoad,
		Message: "unloading (LRU eviction)",
	})

	victim.ps.cancel()  // SIGTERM via context cancellation
	victim.ps.wg.Wait() // wait for supervisor goroutine to exit

	m.mu.Lock() // re-acquire for the caller
	delete(m.procs, victim.name)
	return nil
}

// publishEvent sends an event to the buffered channel, dropping it if full.
func (m *Manager) publishEvent(evt monitor.ServerEvent) {
	select {
	case m.eventCh <- evt:
	default:
	}
}

// healthCheckTimeout returns the effective health check timeout.
func (m *Manager) effectiveHealthTimeout() time.Duration {
	if m.healthTimeout > 0 {
		return m.healthTimeout
	}
	return 120 * time.Second
}

// supervise is the per-model restart loop. It runs until ctx is cancelled
// or (for on-demand models) until the first load attempt fails or the process
// exits after becoming healthy.
func (m *Manager) supervise(ctx context.Context, modelName string) {
	defer m.wg.Done()

	m.mu.RLock()
	ps := m.procs[modelName]
	m.mu.RUnlock()

	// Ensure state is idle and the ready channel is closed on exit (for any
	// reason). This unblocks callers waiting in LoadOrGet and lets Loaded()
	// return false after the supervisor exits.
	defer func() {
		ps.wg.Done()
		ps.mu.Lock()
		ready := ps.ready
		ps.ready = nil
		// Only preserve stateUnloading; evictIfNeeded owns that transition.
		if ps.state != stateUnloading {
			ps.state = stateIdle
		}
		ps.mu.Unlock()
		if ready != nil {
			close(ready)
		}
	}()

	const (
		maxRetries  = 5
		retryWindow = 60 * time.Second
		backoff     = 2 * time.Second
	)

	var (
		attempts    int
		windowStart = time.Now()
		firstLoad   = true
	)

	for {
		select {
		case <-ctx.Done():
			return
		default:
		}

		if time.Since(windowStart) > retryWindow {
			attempts = 0
			windowStart = time.Now()
		}
		if attempts >= maxRetries {
			m.log.Error("max restart retries exceeded, giving up", "model", modelName)
			return
		}

		if attempts > 0 && ps.isWarmup {
			// Before retrying a warmup model, create a fresh ready channel so
			// new callers waiting in LoadOrGet see the correct loading state.
			ps.mu.Lock()
			ps.state = stateLoading
			ps.loadErr = nil
			ps.ready = make(chan struct{})
			ps.mu.Unlock()

			m.log.Info("restarting model", "model", modelName, "attempt", attempts)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
		}

		attempts++

		ps.mu.Lock()
		if !firstLoad {
			ps.restarts++
		}
		ps.startedAt = time.Now()
		params := ps.params
		ps.mu.Unlock()

		cmd, parser, err := m.launch(ctx, modelName, params)
		if err != nil {
			m.log.Error("failed to launch llama-server", "model", modelName, "error", err)
			if !ps.isWarmup {
				m.failLoad(ps, modelName, err)
				return
			}
			continue
		}

		// Wait for llama-server to report its listening port via stdout.
		var port int
		select {
		case port = <-parser.PortCh:
		case <-ctx.Done():
			cmd.Process.Kill()
			cmd.Wait() //nolint:errcheck
			return
		case <-time.After(m.effectiveHealthTimeout()):
			m.log.Error("timed out waiting for listening port", "model", modelName)
			cmd.Process.Kill()
			cmd.Wait() //nolint:errcheck
			if !ps.isWarmup {
				m.failLoad(ps, modelName, fmt.Errorf("timed out waiting for listening port"))
				return
			}
			continue
		}

		ps.mu.Lock()
		ps.port = port
		ps.proc = cmd
		ps.mu.Unlock()

		loadStart := time.Now()
		if err := waitHealthy(ctx, port, m.effectiveHealthTimeout()); err != nil {
			m.log.Error("health check failed on start", "model", modelName, "error", err)
			cmd.Process.Kill()
			cmd.Wait() //nolint:errcheck
			ps.mu.Lock()
			ps.proc = nil
			ps.mu.Unlock()
			if !ps.isWarmup {
				m.failLoad(ps, modelName, err)
				return
			}
			continue
		}

		loadDur := time.Since(loadStart)

		// Transition to healthy and signal all waiters by closing ready.
		ps.mu.Lock()
		ps.state = stateLoaded
		if firstLoad {
			ps.lastUsed = time.Now()
		}
		ready := ps.ready
		ps.ready = nil
		ps.mu.Unlock()

		if ready != nil {
			close(ready)
		}
		firstLoad = false

		m.log.Info("model healthy", "model", modelName, "port", port, "load_duration", loadDur)
		m.publishEvent(monitor.ServerEvent{
			Time:       time.Now(),
			Backend:    modelName,
			Kind:       monitor.EventModelLoad,
			DurationMs: float64(loadDur.Milliseconds()),
			Message:    "loaded",
		})

		exitCh := make(chan error, 1)
		go func() { exitCh <- cmd.Wait() }()

		select {
		case <-ctx.Done():
			<-exitCh
			return

		case exitErr := <-exitCh:
			ps.mu.Lock()
			ps.state = stateIdle
			ps.proc = nil
			ps.mu.Unlock()

			if ctx.Err() != nil {
				return
			}

			oomKilled := false
			if exitErr != nil {
				if ee, ok := errors.AsType[*exec.ExitError](exitErr); ok {
					// OOM killer sends SIGKILL — detect via WaitStatus.
					if ws, ok := ee.Sys().(syscall.WaitStatus); ok && ws.Signal() == syscall.SIGKILL {
						oomKilled = true
						m.log.Error("process killed by SIGKILL (likely OOM)", "model", modelName)
					} else {
						m.log.Warn("process exited unexpectedly", "model", modelName, "exit_code", ee.ExitCode())
					}
				} else {
					m.log.Warn("process exited unexpectedly", "model", modelName, "error", exitErr)
				}
			}

			if !ps.isWarmup {
				// On-demand model crashed; remove and stop.
				m.mu.Lock()
				delete(m.procs, modelName)
				m.mu.Unlock()
				return
			}

			// OOM: back off longer to let the system recover before reloading.
			if oomKilled {
				oomDelay := 30 * time.Second
				m.log.Warn("delaying restart after OOM kill", "model", modelName, "delay", oomDelay)
				select {
				case <-ctx.Done():
					return
				case <-time.After(oomDelay):
				}
			}
		}
		// Warmup model: fall through to retry loop.
	}
}

// failLoad signals a failed on-demand load to all waiters and cleans up.
func (m *Manager) failLoad(ps *procState, modelName string, err error) {
	m.log.Error("model load failed", "model", modelName, "error", err)
	m.publishEvent(monitor.ServerEvent{
		Time:    time.Now(),
		Backend: modelName,
		Kind:    monitor.EventError,
		Message: "load failed: " + err.Error(),
	})

	ps.mu.Lock()
	ps.loadErr = err
	ps.state = stateIdle
	ready := ps.ready
	ps.ready = nil
	ps.mu.Unlock()

	if ready != nil {
		close(ready)
	}

	m.mu.Lock()
	delete(m.procs, modelName)
	m.mu.Unlock()
}

// launch starts a llama-server process with --port 0 and wires its
// stdout/stderr to the event parser. The actual listening port is sent
// to parser.PortCh once llama-server prints its "listening on" line.
func (m *Manager) launch(ctx context.Context, modelName string, params config.ModelParams) (*exec.Cmd, *monitor.EventParser, error) {
	cmd := m.cmdBuilder(ctx, modelName, params)

	cmd.Cancel = func() error {
		if cmd.Process == nil {
			return nil
		}
		return cmd.Process.Signal(syscall.SIGTERM)
	}
	cmd.WaitDelay = 10 * time.Second

	parser := monitor.NewEventParser(m.log, modelName, m.eventCh)
	cmd.Stdout = parser
	cmd.Stderr = parser

	if err := cmd.Start(); err != nil {
		return nil, nil, err
	}
	return cmd, parser, nil
}

// buildArgs constructs the llama-server command-line arguments for a model.
// Port 0 tells llama-server to pick a free port; the actual port is parsed
// from stdout by the event parser.
func buildArgs(modelName string, params config.ModelParams) []string {
	slots := params.Slots
	if slots <= 0 {
		slots = 1
	}
	args := []string{
		"-hf", modelName,
		"--port", "0",
		"--no-webui",
		"--metrics",
		"--parallel", strconv.Itoa(slots),
	}
	if params.GPULayers > 0 {
		args = append(args, "-ngl", strconv.Itoa(params.GPULayers))
	}
	if params.Context > 0 {
		args = append(args, "-c", strconv.Itoa(params.Context))
	}
	if params.Pooling != "" {
		args = append(args, "--embedding", "--pooling", params.Pooling)
	}
	if params.SpecType != "" {
		args = append(args, "--spec-type", params.SpecType)
	}
	if params.DraftMax > 0 {
		args = append(args, "--draft-max", strconv.Itoa(params.DraftMax))
	}
	if params.DraftMin > 0 {
		args = append(args, "--draft-min", strconv.Itoa(params.DraftMin))
	}
	if params.SpecNgramN > 0 {
		args = append(args, "--spec-ngram-size-n", strconv.Itoa(params.SpecNgramN))
	}
	if params.SpecNgramM > 0 {
		args = append(args, "--spec-ngram-size-m", strconv.Itoa(params.SpecNgramM))
	}
	return append(args, params.Extra...)
}

// waitHealthy polls GET /health on the given port every second until it
// returns 200 OK, the context is cancelled, or the timeout elapses.
func waitHealthy(ctx context.Context, port int, timeout time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	url := fmt.Sprintf("http://localhost:%d/health", port)
	client := &http.Client{Timeout: 5 * time.Second}

	// Use a shorter poll interval when the timeout is short (test scenarios).
	interval := time.Second
	if timeout < time.Second {
		interval = timeout / 5
		if interval < 10*time.Millisecond {
			interval = 10 * time.Millisecond
		}
	}

	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
			resp, err := client.Get(url) //nolint:noctx
			if err == nil {
				resp.Body.Close()
				if resp.StatusCode == http.StatusOK {
					return nil
				}
			}
		}
	}
}

